import csv
import io

_DECIMAL_DIGITS = set('0123456789')


class _SimStore:
    """Dry-run stand-in for Store: same get/put interface, local backing."""

    def __init__(self, items):
        self._items = {k: v.copy() for k, v in items.items()}

    def get(self, sku):
        value = self._items.get(sku)
        return None if value is None else value.copy()

    def put(self, item):
        self._items[item['sku']] = item.copy()


def _validate_row(row):
    if row.get('sku') is None or row.get('name') is None or row.get('qty') is None:
        raise ValueError('row is missing required fields sku,name,qty')
    sku = row['sku'].strip()
    name = row['name'].strip()
    qty_raw = row['qty'].strip()
    if not sku:
        raise ValueError('sku must not be empty')
    if not name:
        raise ValueError('name must not be empty')
    if not qty_raw or not all(c in _DECIMAL_DIGITS for c in qty_raw):
        raise ValueError('qty must contain only decimal digits')
    return {'sku': sku, 'name': name, 'qty': int(qty_raw)}


def import_text(text, store, dry_run=False):
    result = {'created': 0, 'updated': 0, 'unchanged': 0, 'changes': []}

    # Parse and validate every row before committing anything.
    items = [_validate_row(row) for row in csv.DictReader(io.StringIO(text))]

    if dry_run:
        target = _SimStore(store.items)
    else:
        target = store

    for item in items:
        before = target.get(item['sku'])
        if before == item:
            result['unchanged'] += 1
            continue
        result['created' if before is None else 'updated'] += 1
        result['changes'].append({'sku': item['sku'], 'before': before, 'after': item.copy()})
        target.put(item)
    return result

